using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Analyzers;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Emit;
using Microsoft.CodeAnalysis.Testing;

public class LedgerIssue2283
{
    private const string LibSource = """
        using MessagePack;

        namespace Lib;

        [MessagePackObject]
        public partial record struct Item<T>([property: Key(0)] string Key);
        """;

    private const string AppSource = """
        using MessagePack;
        using Lib;

        namespace App;

        [MessagePackObject]
        public sealed partial record Cmd([property: Key(0)] string Scope)
        {
            [Key(1)]
            public Item<int> Member { get; init; }
        }
        """;

    private static async Task<CSharpCompilation> CreateAppCompilationAsync()
    {
        ImmutableArray<MetadataReference> net80Refs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        IEnumerable<MetadataReference> baseReferences = net80Refs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);

        CSharpCompilation libCompilation = CSharpCompilation.Create(
            "Lib",
            new[] { CSharpSyntaxTree.ParseText(LibSource, parseOptions) },
            baseReferences,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver libDriver = CSharpGeneratorDriver.Create(new MessagePackGenerator().AsSourceGenerator());
        libDriver = libDriver.RunGeneratorsAndUpdateCompilation(libCompilation, out Compilation libOutputCompilation, out ImmutableArray<Diagnostic> libGenDiagnostics);
        Assert.DoesNotContain(libGenDiagnostics, d => d.Id == "CS8785" || d.Severity == DiagnosticSeverity.Error);

        using MemoryStream libStream = new MemoryStream();
        EmitResult libEmitResult = libOutputCompilation.Emit(libStream);
        Assert.True(libEmitResult.Success, string.Join(Environment.NewLine, libEmitResult.Diagnostics));

        MetadataReference libReference = MetadataReference.CreateFromImage(libStream.ToArray());
        IEnumerable<MetadataReference> appReferences = baseReferences.Append(libReference);

        return CSharpCompilation.Create(
            "App",
            new[] { CSharpSyntaxTree.ParseText(AppSource, parseOptions) },
            appReferences,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
    }

    [Fact]
    public async Task GeneratorSucceedsOnClosedGenericStructFromReferencedAssembly()
    {
        CSharpCompilation appCompilation = await CreateAppCompilationAsync();

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator().AsSourceGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(appCompilation, out Compilation outputCompilation, out ImmutableArray<Diagnostic> generatorDiagnostics);
        GeneratorDriverRunResult runResult = driver.GetRunResult();

        foreach (GeneratorRunResult result in runResult.Results)
        {
            Assert.Null(result.Exception);
        }

        Assert.DoesNotContain(generatorDiagnostics, d => d.Id == "CS8785" || d.Severity == DiagnosticSeverity.Error);
        Assert.Contains(
            runResult.Results.SelectMany(r => r.GeneratedSources),
            s => s.SourceText.ToString().Contains("GeneratedMessagePackResolver", StringComparison.Ordinal));

        ImmutableArray<Diagnostic> compilationErrors = outputCompilation
            .GetDiagnostics()
            .Where(d => d.Severity == DiagnosticSeverity.Error)
            .ToImmutableArray();
        Assert.Empty(compilationErrors);
    }

    [Fact]
    public async Task AnalyzerDoesNotCrashOnClosedGenericStructFromReferencedAssembly()
    {
        CSharpCompilation appCompilation = await CreateAppCompilationAsync();

        ImmutableArray<Diagnostic> analyzerDiagnostics = await appCompilation
            .WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer()))
            .GetAnalyzerDiagnosticsAsync();

        Assert.DoesNotContain(analyzerDiagnostics, d => d.Id == "AD0001");
        Assert.DoesNotContain(analyzerDiagnostics, d => d.Severity == DiagnosticSeverity.Error);
    }
}

