    public async Task ClosedGenericRecordStructFromReferencedAssembly_GeneratesResolverWithoutCrashing()
    {
        string libSource = """
            using MessagePack;

            namespace Lib
            {
                [MessagePackObject]
                public partial record struct Item<T>([property: Key(0)] string Key);
            }
            """;

        string appSource = """
            using MessagePack;
