                }
            }
            """;

        await VerifyClosedGenericStructFromReferencedAssemblyAsync(libSource, appSource);
    }

    [Fact]
    public async Task ClosedGenericStructWithUnkeyedPrivateFieldFromReferencedAssembly_GeneratesResolverWithoutCrashing()
    {
        string libSource = """
            using MessagePack;

            namespace Lib
            {
                [MessagePackObject]
                public struct StructItem<T>
                {
                    private int _unkeyedField;

                    [Key(0)]
                    public T Value { get; set; }
                }
            }
            """;

        string appSource = """
            using MessagePack;
            using Lib;

            namespace App
            {
                [MessagePackObject]
                public partial class Container
                {
                    [Key(0)]
                    public StructItem<string> Item { get; set; }
                }
            }
            """;

        await VerifyClosedGenericStructFromReferencedAssemblyAsync(libSource, appSource);
    }

    private static async Task VerifyClosedGenericStructFromReferencedAssemblyAsync(string libSource, string appSource)
    {
        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        MetadataReference[] baseReferences = frameworkRefs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToArray();
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);

        CSharpCompilation libCompilation = CSharpCompilation.Create(
            "Lib",
            new[] { CSharpSyntaxTree.ParseText(libSource, parseOptions) },
            baseReferences,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver libDriver = CSharpGeneratorDriver.Create(new MessagePackGenerator().AsSourceGenerator());
        libDriver = libDriver.RunGeneratorsAndUpdateCompilation(libCompilation, out Compilation libOutputCompilation, out ImmutableArray<Diagnostic> libGeneratorDiagnostics);
        Assert.Empty(libGeneratorDiagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));

        using MemoryStream libStream = new MemoryStream();
        var libEmitResult = libOutputCompilation.Emit(libStream);
        Assert.True(libEmitResult.Success, string.Join(Environment.NewLine, libEmitResult.Diagnostics));

        MetadataReference libReference = MetadataReference.CreateFromImage(libStream.ToArray());
        MetadataReference[] appReferences = baseReferences.Concat(new[] { libReference }).ToArray();

        CSharpCompilation appCompilation = CSharpCompilation.Create(
            "App",
            new[] { CSharpSyntaxTree.ParseText(appSource, parseOptions) },
            appReferences,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver appDriver = CSharpGeneratorDriver.Create(new MessagePackGenerator().AsSourceGenerator());
        appDriver = appDriver.RunGeneratorsAndUpdateCompilation(appCompilation, out Compilation appOutputCompilation, out ImmutableArray<Diagnostic> appGeneratorDiagnostics);
        GeneratorDriverRunResult runResult = appDriver.GetRunResult();

        Assert.All(runResult.Results, r => Assert.Null(r.Exception));
        Assert.DoesNotContain(appGeneratorDiagnostics, d => d.Id == "CS8785" || d.Severity == DiagnosticSeverity.Error);
        Assert.DoesNotContain(runResult.Diagnostics, d => d.Id == "CS8785" || d.Severity == DiagnosticSeverity.Error);

        var generatedSources = runResult.Results.SelectMany(r => r.GeneratedSources).ToArray();
        Assert.NotEmpty(generatedSources);
        Assert.Contains(generatedSources, s => s.HintName.Contains("Resolver", StringComparison.Ordinal) || s.SourceText.ToString().Contains("GeneratedMessagePackResolver", StringComparison.Ordinal));

        Assert.Empty(appOutputCompilation.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error));

        ImmutableArray<Diagnostic> analyzerDiagnostics = await appCompilation
            .WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer()))
            .GetAnalyzerDiagnosticsAsync();

        Assert.DoesNotContain(analyzerDiagnostics, d => d.Id == "AD0001");
        Assert.Empty(analyzerDiagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));
    }
}

