using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Analyzers;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Emit;
using Microsoft.CodeAnalysis.Testing;
using Xunit;

public class Ledger_2283_Objection2
{
    [Fact]
    public async Task ClosedGenericStruct_WithKeyedFieldAndIndexer_InReferencedAssembly_GeneratesResolver()
    {
        string libSource = """
            using MessagePack;

            namespace Lib
            {
                [MessagePackObject]
                public struct KeyedFieldStruct<T>
                {
                    [Key(0)]
                    public T Value;
                }

                [MessagePackObject]
                public struct KeyedFieldAndIndexerStruct<T>
                {
                    [Key(0)]
                    public T Value;

                    public T this[int index] => this.Value;
                }
            }
            """;

        string appSource = """
            using Lib;
            using MessagePack;

            namespace App
            {
                [MessagePackObject]
                public sealed partial class AppObject
                {
                    [Key(0)]
                    public KeyedFieldStruct<int> FieldStruct { get; set; }

                    [Key(1)]
                    public KeyedFieldAndIndexerStruct<string> IndexerStruct;
                }
            }
            """;

        ImmutableArray<MetadataReference> baseReferences = await GetBaseReferencesAsync();
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        CSharpCompilationOptions compilationOptions = new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary);

        CSharpCompilation libCompilation = CSharpCompilation.Create(
            "Lib",
            new[] { CSharpSyntaxTree.ParseText(libSource, parseOptions) },
            baseReferences,
            compilationOptions);

        MetadataReference libReference = EmitToMetadataReference(libCompilation);

        CSharpCompilation appCompilation = CSharpCompilation.Create(
            "App",
            new[] { CSharpSyntaxTree.ParseText(appSource, parseOptions) },
            baseReferences.Add(libReference),
            compilationOptions);

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator().AsSourceGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(appCompilation, out Compilation outputCompilation, out ImmutableArray<Diagnostic> generatorDiagnostics);
        GeneratorDriverRunResult runResult = driver.GetRunResult();

        Assert.Empty(generatorDiagnostics);
        Assert.Empty(runResult.Diagnostics);
        Assert.All(runResult.Results, r => Assert.Null(r.Exception));

        GeneratedSourceResult[] generatedSources = runResult.Results.SelectMany(r => r.GeneratedSources).ToArray();
        Assert.Contains(generatedSources, s => s.SourceText.ToString().Contains("GeneratedMessagePackResolver"));
        Assert.DoesNotContain(outputCompilation.GetDiagnostics(), d => d.Severity == DiagnosticSeverity.Error);

        ImmutableArray<Diagnostic> appDiagnostics = await appCompilation
            .WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer()))
            .GetAnalyzerDiagnosticsAsync();

        Assert.DoesNotContain(appDiagnostics, d => d.Id == "AD0001");
        Assert.Empty(appDiagnostics);
    }

    [Fact]
    public async Task ClosedGenericStruct_WithUnkeyedField_InReferencedAssembly_ReportsDiagnosticInDefiningAssemblyOnly()
    {
        string libSource = """
            using MessagePack;

            namespace Lib
            {
                [MessagePackObject]
                public struct UnkeyedFieldStruct<T>
                {
                    [Key(0)]
                    public T KeyedValue;

                    public int UnkeyedField;
                }
            }
            """;

        string appSource = """
            using Lib;
            using MessagePack;

            namespace App
            {
                [MessagePackObject]
                public sealed partial class AppObject
                {
                    [Key(0)]
                    public UnkeyedFieldStruct<int> Member { get; set; }
                }
            }
            """;

        ImmutableArray<MetadataReference> baseReferences = await GetBaseReferencesAsync();
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        CSharpCompilationOptions compilationOptions = new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary);

        CSharpCompilation libCompilation = CSharpCompilation.Create(
            "Lib",
            new[] { CSharpSyntaxTree.ParseText(libSource, parseOptions) },
            baseReferences,
            compilationOptions);

        ImmutableArray<Diagnostic> libDiagnostics = await libCompilation
            .WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer()))
            .GetAnalyzerDiagnosticsAsync();

        Assert.DoesNotContain(libDiagnostics, d => d.Id == "AD0001");
        Assert.Contains(libDiagnostics, d => d.Id == "MsgPack004" && d.GetMessage().Contains("UnkeyedField"));

        MetadataReference libReference = EmitToMetadataReference(libCompilation);

        CSharpCompilation appCompilation = CSharpCompilation.Create(
            "App",
            new[] { CSharpSyntaxTree.ParseText(appSource, parseOptions) },
            baseReferences.Add(libReference),
            compilationOptions);

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator().AsSourceGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(appCompilation, out Compilation outputCompilation, out ImmutableArray<Diagnostic> generatorDiagnostics);
        GeneratorDriverRunResult runResult = driver.GetRunResult();

        Assert.Empty(generatorDiagnostics);
        Assert.Empty(runResult.Diagnostics);
        Assert.All(runResult.Results, r => Assert.Null(r.Exception));

        GeneratedSourceResult[] generatedSources = runResult.Results.SelectMany(r => r.GeneratedSources).ToArray();
        Assert.Contains(generatedSources, s => s.SourceText.ToString().Contains("GeneratedMessagePackResolver"));
        Assert.DoesNotContain(outputCompilation.GetDiagnostics(), d => d.Severity == DiagnosticSeverity.Error);

        ImmutableArray<Diagnostic> appDiagnostics = await appCompilation
            .WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer()))
            .GetAnalyzerDiagnosticsAsync();

        Assert.DoesNotContain(appDiagnostics, d => d.Id == "AD0001");
        Assert.DoesNotContain(appDiagnostics, d => d.Id == "MsgPack004");
    }

    private static async Task<ImmutableArray<MetadataReference>> GetBaseReferencesAsync()
    {
        ImmutableArray<MetadataReference> net80Refs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        return net80Refs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToImmutableArray();
    }

    private static MetadataReference EmitToMetadataReference(CSharpCompilation compilation)
    {
        using var stream = new MemoryStream();
        EmitResult emitResult = compilation.Emit(stream);
        Assert.True(emitResult.Success, string.Join(Environment.NewLine, emitResult.Diagnostics));
        return MetadataReference.CreateFromImage(stream.ToArray());
    }
}

