using System;
using System.Collections.Immutable;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Analyzers;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Emit;
using Microsoft.CodeAnalysis.Testing;
using Xunit;

public class Ledger_2283_Objection3
{
    [Fact]
    public async Task NestedClosedGenericValueTypes_FromReferencedAssembly_GenerateResolverWithoutCrash()
    {
        string libSource = """
using MessagePack;

namespace Lib;

public class OuterClass<T>
{
    [MessagePackObject]
    public partial record struct InnerRecordStruct<U>([property: Key(0)] T First, [property: Key(1)] U Second);
}

public struct OuterStruct<T>
{
    [MessagePackObject]
    public partial struct InnerStruct<U>
    {
        [Key(0)]
        public T First { get; set; }

        [Key(1)]
        public U Second { get; set; }
    }
}
""";

        string appSource = """
using MessagePack;
using Lib;

namespace App;

[MessagePackObject]
public sealed partial record Cmd([property: Key(0)] string Scope)
{
    [Key(1)]
    public OuterClass<int>.InnerRecordStruct<string> Member1 { get; init; }

    [Key(2)]
    public OuterStruct<int>.InnerStruct<string> Member2 { get; init; }
}
""";

        await VerifyAppCompilesAndAnalyzesCleanlyAsync(libSource, appSource);
    }

    [Fact]
    public async Task NestedClosedGenericValueType_WithUnkeyedMetadataMember_DoesNotCrashOrReportInvalidLocation()
    {
        string libSource = """
using MessagePack;

namespace Lib;

public class Outer<T>
{
    [MessagePackObject]
    public partial struct InnerWithUnkeyed<U>
    {
        [Key(0)]
        public T First { get; set; }

        [Key(1)]
        public U Second { get; set; }

        public int UnkeyedMetadataMember { get; set; }
    }
}
""";

        string appSource = """
using MessagePack;
using Lib;

namespace App;

[MessagePackObject]
public sealed partial record Cmd([property: Key(0)] string Scope)
{
    [Key(1)]
    public Outer<int>.InnerWithUnkeyed<string> Member { get; init; }
}
""";

        await VerifyAppCompilesAndAnalyzesCleanlyAsync(libSource, appSource);
    }

    private static async Task VerifyAppCompilesAndAnalyzesCleanlyAsync(string libSource, string appSource)
    {
        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        ImmutableArray<MetadataReference> baseReferences = frameworkRefs.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));

        CSharpCompilation libCompilation = CSharpCompilation.Create(
            "Lib",
            new[] { CSharpSyntaxTree.ParseText(libSource, new CSharpParseOptions(LanguageVersion.Latest)) },
            baseReferences,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        using MemoryStream libStream = new MemoryStream();
        EmitResult libEmit = libCompilation.Emit(libStream);
        Assert.True(libEmit.Success, string.Join(Environment.NewLine, libEmit.Diagnostics));
        MetadataReference libReference = MetadataReference.CreateFromImage(libStream.ToArray());

        CSharpCompilation appCompilation = CSharpCompilation.Create(
            "App",
            new[] { CSharpSyntaxTree.ParseText(appSource, new CSharpParseOptions(LanguageVersion.Latest)) },
            baseReferences.Add(libReference),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator().AsSourceGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(appCompilation, out Compilation outputCompilation, out ImmutableArray<Diagnostic> generatorDiagnostics);
        GeneratorDriverRunResult runResult = driver.GetRunResult();

        Assert.All(runResult.Results, r => Assert.Null(r.Exception));
        Assert.DoesNotContain(runResult.Diagnostics, d => d.Id == "CS8785" || d.Severity >= DiagnosticSeverity.Warning);
        Assert.DoesNotContain(generatorDiagnostics, d => d.Id == "CS8785" || d.Severity >= DiagnosticSeverity.Warning);
        Assert.Contains(
            runResult.Results.SelectMany(r => r.GeneratedSources),
            s => s.HintName.Contains("Resolver", StringComparison.OrdinalIgnoreCase)
                 || s.SourceText.ToString().Contains("GeneratedMessagePackResolver", StringComparison.Ordinal));

        using MemoryStream appStream = new MemoryStream();
        EmitResult appEmit = outputCompilation.Emit(appStream);
        Assert.True(appEmit.Success, string.Join(Environment.NewLine, appEmit.Diagnostics));

        ImmutableArray<Diagnostic> analyzerDiagnostics = await appCompilation
            .WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer()))
            .GetAnalyzerDiagnosticsAsync();

        Assert.DoesNotContain(analyzerDiagnostics, d => d.Id == "AD0001");
        Assert.All(analyzerDiagnostics, d =>
        {
            Assert.True(d.Location.IsInSource);
            Assert.True(appCompilation.ContainsSyntaxTree(d.Location.SourceTree));
        });
        Assert.Empty(analyzerDiagnostics);
    }
}

